 const [hover,setHover]=useState(''); const max=Math.max(...cities.map(c=>c.orders),1);
 return <><div className="map"><svg viewBox="0 0 390 490" aria-label="Mapa de Colombia con ciudades de destino" role="img"><rect width="390" height="490" fill="var(--subtle)"/>{neighborOutlines.map((d,i)=><path key={i} d={d} fill="var(--map-neighbor)" stroke="var(--border)"/>)}<path d={colombiaOutline} fill="var(--map-land)" stroke="var(--border)" strokeWidth="1.2"/><text x="235" y="390" style={{fill:'#9d9d9d',stroke:'none',fontSize:11,letterSpacing:2}}>COLOMBIA</text>{cities.map((c,i)=>{const location=demoCities.find(x=>normalize(x[0])===normalize(c.name));if(!location)return null;const {x,y}=mapPoint(location[2],location[3]);return <g key={c.id} onMouseEnter={()=>setHover(c.name)} onMouseLeave={()=>setHover('')}><circle cx={x} cy={y} r={9+Math.sqrt(c.orders/max)*22} fill="#f0e300" stroke="#000" fillOpacity={hover===c.name?1:.8} tabIndex={0} role="button" aria-label={`${c.name}: ${c.orders} pedidos. Filtrar ciudad`} onClick={()=>onSelect(c.name)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect(c.name)}}}><title>{`${c.name}: ${number(c.orders)} pedidos · ${money(c.value)}`}</title></circle>{(i<5||hover===c.name)&&<text x={x+(i%2?22:-15)} y={y+(i%2?-15:30)} textAnchor={i%2?'start':'middle'}>{i+1}. {c.name}</text>}</g>})}</svg></div><div className="map-legend">Menos<span/>Más pedidos</div><p className="muted small" style={{marginTop:8}}>Ubicación aproximada por ciudad; sin direcciones de clientes.</p></>;
